import{_ as d,o as e,c as r,a2 as o}from"./chunks/framework.C0pL2NcE.js";const g=JSON.parse('{"title":"4. Levels","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/levels.md","filePath":"gdd/levels.md"}'),s={name:"gdd/levels.md"};function l(a,t,n,i,h,c){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="_4-levels" tabindex="-1">4. Levels <a class="header-anchor" href="#_4-levels" aria-label="Permalink to &quot;4. Levels&quot;">​</a></h1><p>Twenty pictures; the game plays them from <code>src/game/level-edits.json</code> in the order below, named <code>level_1</code> to <code>level_20</code> in the game and in the Level Editor, whatever name a saved or imported copy carries (<code>GAME_ORDER</code> in <code>src/game/levels.ts</code>).</p><ul><li><strong>Levels 1–10</strong> (ids <code>builtin-10</code> to <code>builtin-19</code>) were drawn by the <a href="./level-design">level design rules</a>: one subject on the empty frame, no outline, 3 colours (4 on levels 5 and 10). Picture size rises in two runs of five, from about 6,000 to 15,000 grains (6,000 · 8,250 · 10,500 · 12,750 · 15,000). They exist only in <code>level-edits.json</code> (no older drawing in <code>levels.ts</code>). The game builds their nests from the picture (rows, seed 0).</li><li><strong>Levels 11–20</strong> are the earlier set (ids <code>builtin-0</code> to <code>builtin-9</code>, their own slots kept), moved back by ten: two small pictures, then eight full-frame scenes.</li></ul><p>&quot;Hand-set&quot; nests come from the Level Editor; the game builds the others. Difficulty rises through picture size, number of colours and nest size (<code>chunk</code>, in blocks before the ×2 nest scale). Not yet checked with the test bot.</p><table tabindex="0"><thead><tr><th>#</th><th>Subject</th><th>Grains</th><th>Blocks</th><th>Colours</th><th>Chunk</th><th>Nests</th></tr></thead><tbody><tr><td>1</td><td>Strawberry</td><td>5,999</td><td>95</td><td>red, green, yellow</td><td>3–5</td><td>rows</td></tr><tr><td>2</td><td>Mushroom</td><td>8,248</td><td>130</td><td>red, orange, white</td><td>3–5</td><td>rows</td></tr><tr><td>3</td><td>Donut</td><td>10,500</td><td>165</td><td>orange, pink, cyan</td><td>3–5</td><td>rows</td></tr><tr><td>4</td><td>Bee</td><td>12,750</td><td>200</td><td>black, yellow, white</td><td>4–6</td><td>rows</td></tr><tr><td>5</td><td>Tulips in a pot</td><td>15,000</td><td>237</td><td>orangered, pink, brown, green</td><td>4–6</td><td>rows</td></tr><tr><td>6</td><td>Whale</td><td>6,000</td><td>96</td><td>navy, white, teal</td><td>3–5</td><td>rows</td></tr><tr><td>7</td><td>Chick</td><td>8,250</td><td>131</td><td>yellow, brown, orangered</td><td>3–5</td><td>rows</td></tr><tr><td>8</td><td>Clownfish</td><td>10,518</td><td>166</td><td>orangered, purple, white</td><td>3–5</td><td>rows</td></tr><tr><td>9</td><td>Octopus</td><td>12,756</td><td>201</td><td>magenta, purple, white</td><td>4–6</td><td>rows</td></tr><tr><td>10</td><td>Ladybug on a leaf</td><td>14,999</td><td>237</td><td>green, red, black, white</td><td>4–6</td><td>rows</td></tr><tr><td>11</td><td>Cherries</td><td></td><td>108</td><td>3</td><td>3–5</td><td>rows</td></tr><tr><td>12</td><td>Ice cream</td><td></td><td>105</td><td>3</td><td>4–6</td><td>rows</td></tr><tr><td>13</td><td>Rocket</td><td></td><td>506</td><td>4</td><td>4–6</td><td>hand-set</td></tr><tr><td>14</td><td>Sleeping cat with flowers</td><td></td><td>506</td><td>4</td><td>4–6</td><td>rows, seed 5</td></tr><tr><td>15</td><td>Black cat peeking</td><td></td><td>507</td><td>6</td><td>5–8</td><td>hand-set</td></tr><tr><td>16</td><td>Sailboat</td><td></td><td>507</td><td>4</td><td>4–6</td><td>hand-set</td></tr><tr><td>17</td><td>Sea turtle</td><td></td><td>506</td><td>4</td><td>4–6</td><td>hand-set</td></tr><tr><td>18</td><td>Panda</td><td></td><td>507</td><td>4</td><td>4–6</td><td>hand-set</td></tr><tr><td>19</td><td>Cottage with garden</td><td></td><td>507</td><td>4</td><td>4–7</td><td>hand-set</td></tr><tr><td>20</td><td>Toucan</td><td></td><td>508</td><td>6</td><td>5–8</td><td>hand-set</td></tr></tbody></table><h2 id="design-rules" tabindex="-1">Design rules <a class="header-anchor" href="#design-rules" aria-label="Permalink to &quot;Design rules&quot;">​</a></h2><p>The full rules for drawing, colouring and building levels are in <a href="./level-design">5. Level design rules</a>.</p><ul><li><p><strong>One area per colour:</strong> keep each colour in one area of the picture. A colour that runs from top to bottom (for example one body colour around the whole picture) makes nests that cannot fill until the very end, and the conveyor overflows.</p></li><li><p><strong>Make and check levels in the Level Editor:</strong> it turns an image into a sand picture in the game&#39;s colours and builds nests that a recorded play wins (see the <a href="./../guide/level-editor">Level Editor guide</a>).</p></li></ul>',8)])])}const p=d(s,[["render",l]]);export{g as __pageData,p as default};
